    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    dangerous_prev = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0.0)
                prev_bids.append(b)
                if b > dangerous_prev:
                    dangerous_prev = b

    if budget <= 0:
        return 0.0

    alive_count = len(alive)
    if alive_count == 0:
        return min(budget, 18.0)

    tight_supply = supply <= 17
    ample_supply = supply >= 22
    urgent = hp <= 3 or no_water_days >= 2
    semi_urgent = hp <= 5 or no_water_days >= 1

    if urgent:
        bid = min(budget, max(62.0, dangerous_prev + 2.0, DAILY_SALARY * 0.92))
        return float(max(0.0, bid))

    if dangerous_prev >= 130:
        if tight_supply:
            bid = min(budget, 58.0)
        elif ample_supply:
            bid = min(budget, 16.0)
        else:
            bid = min(budget, 24.0)
        return float(max(0.0, bid))

    if dangerous_prev >= 90:
        if semi_urgent or tight_supply:
            bid = min(budget, dangerous_prev * 0.72 + 2.0)
        else:
            bid = min(budget, 22.0)
        return float(max(0.0, bid))

    if tight_supply:
        base = 46.0 if semi_urgent else 34.0
    elif ample_supply:
        base = 18.0 if not semi_urgent else 28.0
    else:
        base = 26.0 if not semi_urgent else 38.0

    if prev_bids:
        target = max(base, min(60.0, dangerous_prev + 1.5))
        if dangerous_prev < 35:
            target = max(base, dangerous_prev + 3.0)
    else:
        target = base

    if day >= 8 and hp >= 6 and no_water_days == 0:
        target = min(target, 24.0)

    if budget < 80:
        target = min(target, budget * 0.55)

    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Inspect yesterday bids only
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are likely needed to secure survival
    # If supply is high, we can bid less because competition is less tight.
    # If supply is low, we bid more.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base bid: undercut aggressive bids unless I'm in danger.
    # hp==9 is safe, so prefer moderate bids.
    danger = (hp <= 2.0) or (no_water_days >= 1)

    if danger:
        target = DAILY_SALARY * 0.85
    else:
        # If someone bid extremely high yesterday, slightly increase to avoid being outbid.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = DAILY_SALARY * (0.45 + 0.25 * (1.0 - supply_norm))
        else:
            # Undercut: aim below the highest previous bid but not too low.
            # Use a fraction of highest_prev_bid to stay competitive.
            target = max(DAILY_SALARY * 0.35, highest_prev_bid * 0.75)
            # Adjust for supply tightness.
            target = target * (0.85 + 0.3 * (1.0 - supply_norm))

    # Convert to final bid with budget cap.
    # Also ensure bid is non-negative.
    bid = max(0.0, min(budget, target))

    # If budget is very low, still bid enough to not waste the day.
    if budget < DAILY_SALARY * 0.2:
        bid = max(0.0, min(budget, DAILY_SALARY * 0.15))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        if my_status['hp'] < EPISODE_DAYS:
            return min(my_status['budget'], DAILY_SALARY * 0.4)
        return 0.1

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid_amount = DAILY_SALARY * 0.5

    if my_status['hp'] <= 3 or my_status['no_water_days'] >= 1:
        bid_amount = DAILY_SALARY * 0.95
        if highest_prev_bid > 0:
            bid_amount = max(bid_amount, highest_prev_bid + 5)
    elif my_status['hp'] <= 6:
        bid_amount = DAILY_SALARY * 0.8
        if highest_prev_bid > 0:
            bid_amount = max(bid_amount, highest_prev_bid + 3)
    else:
        bid_amount = DAILY_SALARY * 0.6
        if highest_prev_bid > 0:
            if highest_prev_bid < DAILY_SALARY * 0.75:
                bid_amount = max(bid_amount, highest_prev_bid + 1.5)
            else:
                bid_amount = DAILY_SALARY * 0.5

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] <= 5:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.99)
        elif my_status['hp'] <= 7 and my_status['budget'] > DAILY_SALARY * 2:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.9)

    final_bid = min(my_status['budget'], bid_amount)

    if my_status['hp'] < EPISODE_DAYS and final_bid < DAILY_SALARY * 0.1:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.1)

    if final_bid <= 0:
        final_bid = 0.1

    return final_bid

